# ============================================================
# SHEET DEFINITIONS
# ============================================================
TESTPLAN_COLUMNS = [
    "Index", "SS / Module", "Feature", "Test Case Name", "Test Description",
    "Speed", "Mode", "Memory Start Offset", "Memory End Offset", "Remarks",
    "Test Steps / Procedure", "Impacted Registers", "Validation / Acceptance Criteria",
    "Code Generation"
]

METADATA_COLUMNS = [
    "Index", "Test Case Name", "Meta Test Description", "Meta Test Steps / Procedure",
    "Meta Impacted Registers", "Meta Validation / Acceptance Criteria",
    "Meta Headers", "Meta Macros", "Meta Arrays"
]

def generate_workbook():
    # IST timestamp
    ist = timezone(timedelta(hours=5, minutes=30))
    now_ist = datetime.now(ist)
    timestamp = now_ist.strftime("%Y%m%d_%H%M%S")
    filename = f"MIPI_DSI_TestPlan_{timestamp}.xlsx"
    
    # Determine output path
    script_dir = os.path.dirname(os.path.abspath(__file__))
    filepath = os.path.join(script_dir, filename)
    
    # Create workbook
    wb = Workbook()
    
    # ---- TestPlan Sheet ----
    ws_tp = wb.active
    ws_tp.title = "TestPlan"
    
    # Header formatting
    header_font = Font(bold=True, color="FFFFFF", size=11)
    header_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
    header_align = Alignment(horizontal="center", vertical="center", wrap_text=True)
    cell_align = Alignment(vertical="top", wrap_text=True)
    
    # Write TestPlan headers
    for col_idx, col_name in enumerate(TESTPLAN_COLUMNS, 1):
        cell = ws_tp.cell(row=1, column=col_idx, value=col_name)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = header_align
    
    # Write TestPlan data
    for row_idx, row_data in enumerate(json_data, 2):
        for col_idx, col_name in enumerate(TESTPLAN_COLUMNS, 1):
            value = row_data.get(col_name, "")
            cell = ws_tp.cell(row=row_idx, column=col_idx, value=value)
            cell.alignment = cell_align
    
    # Freeze first row
    ws_tp.freeze_panes = "A2"
    
    # ---- MetaData Sheet ----
    ws_md = wb.create_sheet(title="MetaData")
    
    # Write MetaData headers
    for col_idx, col_name in enumerate(METADATA_COLUMNS, 1):
        cell = ws_md.cell(row=1, column=col_idx, value=col_name)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = header_align
    
    # Write MetaData data
    for row_idx, row_data in enumerate(json_data, 2):
        for col_idx, col_name in enumerate(METADATA_COLUMNS, 1):
            value = row_data.get(col_name, "")
            cell = ws_md.cell(row=row_idx, column=col_idx, value=value)
            cell.alignment = cell_align
    
    # Freeze first row
    ws_md.freeze_panes = "A2"
    
    # Set MetaData sheet to veryHidden
    ws_md.sheet_state = "veryHidden"
    
    # ---- Auto-size columns ----
    MAX_WIDTH = 60
    for ws in [ws_tp, ws_md]:
        for col_idx in range(1, ws.max_column + 1):
            max_len = 0
            col_letter = get_column_letter(col_idx)
            for row in ws.iter_rows(min_col=col_idx, max_col=col_idx, values_only=False):
                for cell in row:
                    if cell.value:
                        lines = str(cell.value).split('\n')
                        for line in lines:
                            max_len = max(max_len, len(line))
            adjusted = min(max_len + 4, MAX_WIDTH)
            ws.column_dimensions[col_letter].width = max(adjusted, 12)
    
    # Save workbook
    wb.save(filepath)
    print(f"Workbook saved: {filepath}")
    print(f"Filename: {filename}")
    
    # Validate
    if not os.path.exists(filepath):
        print("VALIDATION FAILED: File does not exist")
        return None, None
    
    file_size = os.path.getsize(filepath)
    if file_size == 0:
        print("VALIDATION FAILED: File size is 0")
        return None, None
    
    # Reopen to validate
    wb_check = load_workbook(filepath)
    sheets = wb_check.sheetnames
    if "TestPlan" not in sheets:
        print("VALIDATION FAILED: TestPlan sheet missing")
        return None, None
    if "MetaData" not in sheets:
        print("VALIDATION FAILED: MetaData sheet missing")
        return None, None
    
    tp_rows = wb_check["TestPlan"].max_row - 1  # exclude header
    md_rows = wb_check["MetaData"].max_row - 1  # exclude header
    
    print(f"VALIDATION PASSED")
    print(f"File size: {file_size} bytes")
    print(f"TestPlan rows: {tp_rows}")
    print(f"MetaData rows: {md_rows}")
    print(f"Sheets: {sheets}")
    
    return filepath, filename

if __name__ == "__main__":
    filepath, filename = generate_workbook()
    if filepath:
        print(f"\nSUCCESS: {filename}")
    else:
        print("\nFAILURE")
        sys.exit(1)
